'use strict';
let recipeDraft=null,recipeDraftDirty=false;
function wellnessState(){const w=state.wellness||(state.wellness={});w.pantry=Array.isArray(w.pantry)?w.pantry:[];w.recipes=Array.isArray(w.recipes)?w.recipes:[];w.shopping=Array.isArray(w.shopping)?w.shopping:[];w.preferences=w.preferences||{diet:'No specific diet',allergies:'',avoid:'',favorites:''};w.memory=w.memory||{enabled:false,notes:[]};w.waterEvents=Array.isArray(w.waterEvents)?w.waterEvents:[];return w;}
function wellnessId(){return globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);}
function localDay(value=new Date()){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function wellnessCoachContext(){const w=wellnessState();return {pantry:w.pantry.slice(0,40),foodPreferences:w.preferences,savedNotes:w.memory.enabled?w.memory.notes.slice(0,12):[]};}
function wellnessTiles(){return `<div class="wellness-tiles">${[['pantry','food','Pantry & budget','Plan with what you have'],['recipes','leaf','My recipes','Ingredients, portions & sauces'],['shopping','check','Shopping list','Your editable grocery list'],['food-preferences','heart','Food preferences','Allergies, favorites & dislikes'],['weekly-review','chart','Weekly review','Your actual logged activity'],['coach-memory','chat','Coach memory','View, edit & clear saved notes']].map(([action,icon,name,detail])=>`<button data-action="${action}" class="wellness-tile">${ic(icon)}<span><strong>${name}</strong><small>${detail}</small></span>${ic('arrow')}</button>`).join('')}</div>`;}
function wellnessHub(){showModal('Your everyday toolkit',`<p class="subtle">Plan, cook and build habits around your day.</p>${wellnessTiles()}`);}
function openPantry(){const w=wellnessState();showModal('Pantry & budget',`<p class="subtle">Add ingredients you already have. Your coach can help turn them into meal ideas within your budget.</p><form id="pantry-form"><label class="field"><span>Ingredients on hand · one per line</span><textarea id="pantry-items" rows="6" maxlength="2000" placeholder="Rice\nEggs\nCabbage\nChicken">${esc(w.pantry.join('\n'))}</textarea></label><label class="field"><span>Food budget per day (₱)</span><input id="pantry-budget" type="number" min="50" max="3000" value="${state.budget}" required></label><div class="sheet-actions"><button class="secondary" type="submit">Save pantry</button><button class="primary" type="button" data-action="pantry-coach">Ask my coach for meal ideas</button></div></form><p class="field-help">Prices depend on your store and location. Check the coach’s estimates before shopping. Review every ingredient against your food preferences.</p><button class="text-btn" data-action="recipes">Open my recipes →</button>`);}
function savePantry(){const w=wellnessState();w.pantry=$('#pantry-items').value.split('\n').map(x=>x.trim().slice(0,80)).filter(Boolean).slice(0,40);state.budget=boundedNumber($('#pantry-budget').value,50,3000,100);save();}
function pantryCoach(){savePantry();if((state.coachType!=='custom'&&state.coach.engine==='offline')||(state.coachType==='custom'&&(!state.coach.connection.live||state.coach.connection.provider==='demo'))){toast('Choose a live AI connection in coach settings for pantry meal ideas.');return;}const w=wellnessState();if(!w.pantry.length){toast('Add some ingredients first.');return;}closeModal();sendMessage(`Plan meals using the pantry ingredients in my saved app context and my ₱${state.budget} daily food budget. Ask about amounts if needed, suggest only a short shopping list for missing ingredients, label any prices as estimates, and consider my saved food preferences.`);}
function openFoodPreferences(){const p=wellnessState().preferences;showModal('Food preferences & allergies',`<form id="food-preferences-form"><label class="field"><span>Eating preference</span><select id="food-diet">${['No specific diet','Vegetarian','Vegan','Pescatarian','Halal preference'].map(x=>`<option ${p.diet===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field"><span>Food allergies</span><textarea id="food-allergies" maxlength="600" placeholder="e.g. peanuts, shrimp">${esc(p.allergies)}</textarea></label><label class="field"><span>Foods or ingredients to avoid</span><textarea id="food-avoid" maxlength="600" placeholder="Dislikes or other restrictions">${esc(p.avoid)}</textarea></label><label class="field"><span>Favorite foods</span><textarea id="food-favorites" maxlength="600">${esc(p.favorites)}</textarea></label><p class="wellness-notice">These details guide coach suggestions and are sent with live coaching requests. Food photos and catalog entries cannot confirm allergens or cross-contact. Check ingredient labels and preparation yourself.</p><button class="primary">Save food preferences</button></form>`);}
function openRecipes(){const w=wellnessState();showModal('My recipes',`<p class="subtle">Build a recipe from reference foods or add your own ingredient details. Adjust portions, sauces and seasonings.</p><button class="primary" data-action="new-recipe">${ic('plus')}Create a recipe</button><div class="recipe-list">${w.recipes.map(r=>`<article class="recipe-card"><h3>${esc(r.name)}</h3><p>${r.ingredients.length} ingredients · ${r.servings} portions</p><div class="recipe-actions"><button class="text-btn" data-edit-recipe="${esc(r.id)}">Edit recipe</button><button class="text-btn" data-recipe-shopping="${esc(r.id)}">Add to shopping list</button><button class="text-btn" data-log-recipe="${esc(r.id)}">Log one portion</button><button class="text-btn" data-plan-recipe="${esc(r.id)}">Plan for lunch</button><button class="text-btn danger-text" data-delete-recipe="${esc(r.id)}">Delete</button></div></article>`).join('')||'<div class="empty">Your recipes will appear here.</div>'}</div>`);}
function recipeIngredientFood(item){if(item.foodId)return foods.find(f=>f.id===item.foodId)||{name:item.name,kcal:null,protein:null,sodium:null,sugar:null};return {id:'custom-ingredient',name:item.name,serving:'100 g reference',kcal:item.kcal??null,protein:item.protein??null,sodium:item.sodium??null,sugar:item.sugar??null};}
function recipeTotals(recipe){const result={};for(const k of ['kcal','protein','sodium','sugar']){let sum=0,missing=false;for(const item of recipe.ingredients){const f=recipeIngredientFood(item);if(typeof f[k]==='number')sum+=f[k]*item.grams/100;else missing=true;}result[k]=missing?null:Math.round(sum/recipe.servings*10)/10;result[k+'Known']=Math.round(sum/recipe.servings*10)/10;}return result;}
function openRecipeEditor(id){const found=wellnessState().recipes.find(r=>r.id===id);recipeDraft=found?cloneCoach(found):{id:wellnessId(),name:'My recipe',servings:2,ingredients:[]};recipeDraftDirty=false;recipeEditor();}
function recipeEditor(){const r=recipeDraft;if(!r)return;const t=recipeTotals(r);activeModal='recipe';showModal('Recipe editor',`<button class="text-btn" data-action="recipes">← My recipes</button><form id="recipe-form"><label class="field"><span>Recipe name</span><input id="recipe-name" value="${esc(r.name)}" maxlength="80" required></label><label class="field"><span>How many portions does the whole recipe make?</span><input id="recipe-servings" type="number" min="1" max="30" step="0.5" value="${r.servings}" required></label><div class="recipe-ingredients">${r.ingredients.map((item,i)=>`<div class="recipe-ingredient"><strong>${esc(recipeIngredientFood(item).name)}</strong><div class="field-row"><label class="field"><span>Edible weight (g)</span><input data-ingredient-grams="${i}" type="number" min="1" max="10000" step="1" value="${item.grams}"></label><label class="field"><span>Cost for this amount (₱) · optional</span><input data-ingredient-cost="${i}" type="number" min="0" max="100000" step="0.01" value="${item.cost??''}"></label></div><button type="button" class="text-btn danger-text" data-remove-ingredient="${i}">Remove ingredient</button></div>`).join('')}</div><div class="field-row"><label class="field"><span>Add ingredient from food guide</span><select id="recipe-food">${foods.map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></label><button type="button" class="secondary recipe-add" data-action="recipe-add">${ic('plus')}Add ingredient</button></div><button type="button" class="text-btn" data-action="recipe-custom-ingredient">Add sauce, seasoning or other ingredient manually</button><div id="recipe-estimates">${recipeEstimateMarkup(r,t)}</div><p class="wellness-notice">Weights refer to the catalog’s preparation variant. Select ingredients that match your recipe. Values from labels or catalog foods are estimates; cooking yield and ingredients change the result. Missing values stay unknown.</p><div class="sheet-actions"><button class="secondary" type="button" data-action="recipe-save-shopping">Save & add to shopping list</button><button class="primary" type="submit">Save recipe</button></div></form>`);activeModal='recipe';}
function recipeEstimateMarkup(r,t=recipeTotals(r)){return `<div class="recipe-estimates"><h3>Per portion · estimate</h3><div class="scan-nutrients">${[['kcal','kcal','Energy'],['protein','g','Protein'],['sodium','mg','Sodium'],['sugar','g','Total sugar']].map(([k,unit,label])=>`<div><b>${t[k]===null?'Unknown':t[k]+' '+unit}</b><small>${label}${t[k]===null&&t[k+'Known']>0?' · at least '+t[k+'Known']+' '+unit+' known':''}</small></div>`).join('')}</div>${r.ingredients.length?sodiumGuidance([{food:{...t,name:r.name},portion:1}]):''}</div>`;}
function refreshRecipeDraft(){if(!recipeDraft||!$('#recipe-name'))return;recipeDraft.name=$('#recipe-name').value.trim().slice(0,80)||'My recipe';recipeDraft.servings=boundedNumber($('#recipe-servings').value,1,30,1);for(const el of document.querySelectorAll('[data-ingredient-grams]'))recipeDraft.ingredients[+el.dataset.ingredientGrams].grams=boundedNumber(el.value,1,10000,100);for(const el of document.querySelectorAll('[data-ingredient-cost]'))recipeDraft.ingredients[+el.dataset.ingredientCost].cost=optionalNumber(el.value,0,100000);recipeDraftDirty=true;}
function saveRecipe(toShopping=false){refreshRecipeDraft();if(!recipeDraft?.ingredients.length){toast('Add at least one ingredient.');return false;}const w=wellnessState(),copy=cloneCoach(recipeDraft),index=w.recipes.findIndex(x=>x.id===copy.id);if(index<0)w.recipes.push(copy);else w.recipes[index]=copy;save();if(toShopping){addRecipeToShopping(copy.id);openShopping();}else{openRecipes();toast('Recipe saved.');}return true;}
function customIngredientModal(){refreshRecipeDraft();showModal('Add your own ingredient',`<form id="custom-ingredient-form"><label class="field"><span>Ingredient name</span><input name="name" maxlength="80" required placeholder="e.g. soy sauce"></label><label class="field"><span>Amount used (g)</span><input name="grams" type="number" min="1" max="10000" value="10" required></label><p class="subtle">Optional nutrition per 100 g, copied from the ingredient’s label. Leave blank when unknown.</p><div class="field-row">${[['kcal','Energy (kcal)'],['protein','Protein (g)'],['sodium','Sodium (mg)'],['sugar','Total sugar (g)']].map(([k,label])=>`<label class="field"><span>${label} per 100 g</span><input name="${k}" type="number" min="0" max="100000" step="0.1"></label>`).join('')}</div><button class="primary">Add to recipe</button></form>`);}
function addRecipeToShopping(id,scale=1){const w=wellnessState(),r=w.recipes.find(x=>x.id===id);if(!r)return;for(const i of r.ingredients)w.shopping.push({id:wellnessId(),name:recipeIngredientFood(i).name,quantity:Math.round(i.grams*scale*10)/10+' g',cost:i.cost===null||i.cost===undefined?null:Math.round(i.cost*scale*100)/100,checked:false,recipe:r.name});save();toast('Recipe ingredients added to your shopping list.');}
function logRecipe(id){const r=wellnessState().recipes.find(x=>x.id===id);if(!r)return;const t=recipeTotals(r);setVibeMoment('meal');state.meals.push({uid:wellnessId(),name:r.name,emoji:'🍲',portion:1,meal:'Meal',source:'recipe',nutritionSource:'User recipe · reference ingredients and label values',nutritionVerified:false,loggedAt:new Date().toISOString(),kcal:t.kcal,sodium:t.sodium,sugar:t.sugar,protein:t.protein});save();toast('One recipe portion added to your food log.');}
function openShopping(){const w=wellnessState(),remaining=w.shopping.filter(i=>!i.checked),known=remaining.reduce((n,i)=>n+(i.cost??0),0),partial=remaining.some(i=>i.cost===null);showModal('Shopping list',`<div class="shopping-summary"><strong>${remaining.length} items to pick up</strong><p>${partial?'At least ':''}₱${known.toFixed(2)} estimated · ${partial?'some prices missing':'your entered prices'}</p><small>Daily food budget: ₱${state.budget}. Grocery purchases may cover several days.</small></div><button class="secondary" data-action="plan-shopping">Add recipe ingredients from my daily plan</button><p class="field-help">Link a saved recipe with “Plan for lunch” in My recipes. Ingredients are scaled to the planned portions.</p><div class="shopping-items">${w.shopping.map(i=>`<div class="shopping-item ${i.checked?'is-checked':''}"><label><input type="checkbox" data-shopping-check="${esc(i.id)}" ${i.checked?'checked':''}><span><strong>${esc(i.name)}</strong><small>${esc(i.quantity)}${i.cost===null?' · Price not entered':' · ₱'+Number(i.cost).toFixed(2)}${i.recipe?' · '+esc(i.recipe):''}</small></span></label><button class="text-btn" data-edit-shopping="${esc(i.id)}">Edit</button><button class="delete-btn" data-delete-shopping="${esc(i.id)}" aria-label="Remove ${esc(i.name)}">${ic('trash')}</button></div>`).join('')||'<div class="empty">Add items here or send ingredients from a saved recipe.</div>'}</div><form id="shopping-form"><h3 class="wellness-form-heading">Add an item</h3><label class="field"><span>Item</span><input name="name" maxlength="100" required></label><div class="field-row"><label class="field"><span>Quantity</span><input name="quantity" maxlength="60" placeholder="e.g. 500 g" required></label><label class="field"><span>Estimated total cost (₱) · optional</span><input name="cost" type="number" min="0" max="100000" step="0.01"></label></div><button class="primary">Add item</button></form><button class="text-btn" data-action="clear-shopping">Remove checked items</button>`);}
function editShoppingItem(id){const i=wellnessState().shopping.find(x=>x.id===id);if(!i)return;showModal('Edit shopping item',`<form id="shopping-edit-form" data-id="${esc(id)}"><label class="field"><span>Item</span><input name="name" value="${esc(i.name)}" maxlength="100" required></label><label class="field"><span>Quantity</span><input name="quantity" value="${esc(i.quantity)}" maxlength="60" required></label><label class="field"><span>Estimated total cost (₱) · optional</span><input name="cost" type="number" min="0" max="100000" step="0.01" value="${i.cost??''}"></label><button class="primary">Save item</button></form>`);}
function openCoachMemory(){const m=wellnessState().memory;showModal('Coach memory',`<p class="subtle">Choose the notes your coach can use across conversations. Nothing is added automatically.</p><form id="memory-form"><label class="memory-toggle"><input id="memory-enabled" type="checkbox" ${m.enabled?'checked':''}><span>Include my saved notes in live coaching</span></label><label class="field"><span>Saved notes · one per line</span><textarea id="memory-notes" rows="7" maxlength="2400" placeholder="I prefer quick meals.\nEncourage me gently after a busy day.">${esc(m.notes.join('\n'))}</textarea></label><p class="wellness-notice">Up to 12 notes. Enabled notes are sent to your selected AI provider along with current app preferences. Turning this off stops sending these notes; recent chat history still supplies conversation context. Clearing notes does not delete previous messages or copies already sent to a provider.</p><div class="sheet-actions"><button type="button" class="secondary" data-action="clear-memory">Delete all saved notes</button><button class="primary">Save memory settings</button></div></form>`);}
function weeklyReviewData(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {date:localDay(d),meals:0,minutes:0,water:0,sodium:0,missingSodium:false};}),byDate=new Map(days.map(d=>[d.date,d]));for(const m of state.meals){const d=byDate.get(localDay(m.loggedAt));if(!m.loggedAt||!d)continue;d.meals++;if(typeof m.sodium==='number')d.sodium+=m.sodium;else d.missingSodium=true;}for(const a of state.activities){const d=byDate.get(localDay(a.loggedAt));if(a.loggedAt&&d)d.minutes+=Number(a.minutes)||0;}for(const e of wellnessState().waterEvents){const d=byDate.get(localDay(e.loggedAt));if(d)d.water+=e.glasses||1;}return days;}
function weeklyReviewMarkup(){const days=weeklyReviewData(),meals=days.reduce((n,d)=>n+d.meals,0),minutes=days.reduce((n,d)=>n+d.minutes,0),water=days.reduce((n,d)=>n+d.water,0),active=days.filter(d=>d.meals||d.minutes||d.water).length;return `<div class="review-summary"><div><b>${meals}</b><small>Meals logged</small></div><div><b>${minutes} min</b><small>Movement logged</small></div><div><b>${water}</b><small>Water check-ins</small></div></div><div class="review-chart" aria-label="Meals logged over the last seven days">${days.map(d=>`<div><b>${d.meals}</b><span style="height:${Math.max(4,Math.min(110,d.meals*18))}px"></span><small>${new Date(d.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short'})}</small></div>`).join('')}</div><div class="review-table-wrap"><table class="review-table"><thead><tr><th>Date</th><th>Meals</th><th>Move</th><th>Known sodium</th></tr></thead><tbody>${days.map(d=>`<tr><td>${d.date.slice(5)}</td><td>${d.meals}</td><td>${d.minutes} min</td><td>${d.meals?(d.missingSodium?'≥ ':'')+Math.round(d.sodium)+' mg'+(d.missingSodium?' · partial':''):'—'}</td></tr>`).join('')}</tbody></table></div><div class="wellness-notice"><strong>${active?active+' day'+(active===1?'':'s')+' with recorded activity.':'Your first real check-in starts your review.'}</strong><p>Only dated records from the last seven calendar days are included. Older undated demo entries are excluded. Missing food values keep sodium totals partial. These are logged activities, not measured health outcomes.</p></div>`;}
function openWeeklyReview(){showModal('Your weekly review',weeklyReviewMarkup());}
function actualProgress(){return `<section class="screen">${header()}${title('Your week, one small win at a time')}<p class="subtle" style="margin-top:12px">A review of what you actually recorded in KainCheck.</p><div class="actual-review">${weeklyReviewMarkup()}</div><button class="secondary" data-action="wellness-tools">Open your everyday toolkit</button>${state.coach.vibe?'<button class="text-btn" data-action="vibe-card">✨ Open your Vibe card</button>':''}</section>`;}
function installWellness(){
 Object.assign(actions,{'wellness-tools':wellnessHub,pantry:openPantry,recipes:openRecipes,shopping:openShopping,'food-preferences':openFoodPreferences,'weekly-review':openWeeklyReview,'coach-memory':openCoachMemory,'pantry-coach':pantryCoach,'plan-shopping':()=>{const w=wellnessState(),meals=state.plan.filter(p=>p.kind==='meal'),linked=meals.filter(p=>w.recipes.some(r=>r.id===p.recipeId));for(const p of linked){const r=w.recipes.find(r=>r.id===p.recipeId);addRecipeToShopping(r.id,(p.recipePortions||1)/r.servings);}openShopping();toast(linked.length?'Planned recipe ingredients added. Review pantry items before buying.':'Link a saved recipe to your plan first in My recipes.');},'new-recipe':()=>openRecipeEditor(),'recipe-add':()=>{refreshRecipeDraft();if(recipeDraft.ingredients.length>=40){toast('Use up to 40 ingredients per recipe.');return;}recipeDraft.ingredients.push({foodId:$('#recipe-food').value,grams:100,cost:null});recipeEditor();},'recipe-custom-ingredient':customIngredientModal,'recipe-save-shopping':()=>saveRecipe(true),'clear-shopping':()=>{wellnessState().shopping=wellnessState().shopping.filter(i=>!i.checked);save();openShopping();},'clear-memory':()=>{wellnessState().memory={enabled:false,notes:[]};save();openCoachMemory();toast('Saved memory notes deleted.');}});
 const baseWater=actions.water;actions.water=()=>{wellnessState().waterEvents.push({loggedAt:new Date().toISOString(),glasses:1});baseWater();};
 const baseToday=today;today=()=>baseToday().replace('<div class="section-top"><h2>Your daily plan</h2>',`<button class="wellness-home-entry" data-action="wellness-tools">${ic('leaf')}<span><strong>Your everyday toolkit</strong><small>Pantry, recipes, shopping & more</small></span>${ic('arrow')}</button><div class="section-top"><h2>Your daily plan</h2>`);
 const baseProfile=profile;profile=()=>baseProfile().replace('<button class="subscription-banner"',`<button class="wellness-home-entry" data-action="wellness-tools">${ic('leaf')}<span><strong>Pantry, recipes & preferences</strong><small>Open your everyday toolkit</small></span>${ic('arrow')}</button><button class="subscription-banner"`);
 progress=actualProgress;
 document.addEventListener('input',e=>{if(e.target.closest('#recipe-form')){refreshRecipeDraft();$('#recipe-estimates').innerHTML=recipeEstimateMarkup(recipeDraft);}});
 document.addEventListener('change',e=>{if(e.target.dataset.shoppingCheck){const i=wellnessState().shopping.find(i=>i.id===e.target.dataset.shoppingCheck);if(i){i.checked=e.target.checked;save();openShopping();}}});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.editRecipe)openRecipeEditor(d.editRecipe);if(d.planRecipe){const r=wellnessState().recipes.find(r=>r.id===d.planRecipe);if(r){const old=state.plan.find(p=>p.kind==='meal'),item={id:old?.id||'lunch',kind:'meal',time:old?.time||'12:30',title:r.name,detail:'1 portion of your saved recipe',recipeId:r.id,recipePortions:1,emoji:'🍲',done:false};if(old)state.plan[state.plan.indexOf(old)]=item;else state.plan.push(item);save();toast('Recipe added to your daily lunch plan.');}}if(d.recipeShopping){addRecipeToShopping(d.recipeShopping);openShopping();}if(d.logRecipe)logRecipe(d.logRecipe);if(d.deleteRecipe){wellnessState().recipes=wellnessState().recipes.filter(r=>r.id!==d.deleteRecipe);save();openRecipes();}if(d.removeIngredient!==undefined){refreshRecipeDraft();recipeDraft.ingredients.splice(+d.removeIngredient,1);recipeEditor();}if(d.editShopping)editShoppingItem(d.editShopping);if(d.deleteShopping){wellnessState().shopping=wellnessState().shopping.filter(i=>i.id!==d.deleteShopping);save();openShopping();}});
 document.addEventListener('submit',e=>{const f=e.target,data=new FormData(f),w=wellnessState();if(f.id==='pantry-form'){savePantry();toast('Pantry and daily budget saved.');}if(f.id==='recipe-form')saveRecipe();if(f.id==='custom-ingredient-form'){if(recipeDraft.ingredients.length>=40){toast('Use up to 40 ingredients per recipe.');return;}recipeDraft.ingredients.push({name:String(data.get('name')).trim().slice(0,80),grams:boundedNumber(data.get('grams'),1,10000,10),cost:null,...Object.fromEntries(['kcal','protein','sodium','sugar'].map(k=>[k,optionalNumber(data.get(k),0,100000)]))});recipeEditor();}if(f.id==='food-preferences-form'){w.preferences={diet:$('#food-diet').value,allergies:$('#food-allergies').value.slice(0,600),avoid:$('#food-avoid').value.slice(0,600),favorites:$('#food-favorites').value.slice(0,600)};save();closeModal();render(true);toast('Food preferences saved.');}if(['shopping-form','shopping-edit-form'].includes(f.id)){const values={name:String(data.get('name')).trim().slice(0,100),quantity:String(data.get('quantity')).trim().slice(0,60),cost:optionalNumber(data.get('cost'),0,100000)};if(f.id==='shopping-form')w.shopping.push({id:wellnessId(),...values,checked:false});else Object.assign(w.shopping.find(i=>i.id===f.dataset.id)||{},values);save();openShopping();}if(f.id==='memory-form'){w.memory={enabled:$('#memory-enabled').checked,notes:$('#memory-notes').value.split('\n').map(x=>x.trim().slice(0,200)).filter(Boolean).slice(0,12)};save();closeModal();toast('Memory settings saved.');}});
}
